def parse_code(
    source: str,
    file_path: str | Path,
) -> ParsedCode | None:

    path = Path(file_path)

    if path.suffix.lower() == ".py":
        try:
            return parse_python(source)
        except SyntaxError:
            return None

    return None

def test_apply_modifies_file(
    tmp_path,
):
    proposal = make_proposal(
        tmp_path
    )

    applier = SafePatchApplier(
        tmp_path
    )

    result = applier.apply(
        proposal
    )

    assert result.status == (
        ChangeStatus.APPLIED
    )

    assert (
        tmp_path
        / "app.py"
    ).read_text(
        encoding="utf-8"
    ) == "print('new')\n"

def test_empty_change_is_supported(
    tmp_path: Path,
):
    file_path = (
        tmp_path / "app.py"
    )

    original = (
        "print('hello')\n"
    )

    file_path.write_text(
        original,
        encoding="utf-8",
    )

    response = PatchGenerationResponse(
        description=(
            "No safe change can be generated "
            "from the available evidence."
        ),
        changes=[],
    )

    generator = LLMPatchGenerator(
        llm=FakeStructuredLLM(
            response
        )
    )

    proposal = generator.generate(
        repository_id="test-repo",
        repository_root=tmp_path,
        query="Fix something.",
        files=[
            {
                "path": "app.py",
                "content": original,
            }
        ],
        evidence=[],
    )

    assert proposal.is_empty
    assert proposal.changes == []

def make_proposal(
    tmp_path: Path,
):
    file_path = (
        tmp_path / "app.py"
    )

    file_path.write_text(
        "def hello():\n"
        "    return 'hello'\n",
        encoding="utf-8",
    )

    change = create_file_change(
        repository_root=tmp_path,
        path="app.py",
        proposed_content=(
            "def hello():\n"
            "    return 'world'\n"
        ),
        reason="Update greeting.",
    )

    return create_change_proposal(
        repository_id="test-repo",
        description="Update greeting.",
        changes=[change],
    )

